llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Alvimopan, a zwitterionic N-substituted piperidine containing a carboxylic acid and phenyl group, has an absolute oral bioavailability of only 6% in humans; the query shares the same piperidine-carboxylic acid zwitterionic core and N-substitution pattern, providing affirmative low-F evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Cilomilast, the closest analogue by Morgan similarity, has ~96% absolute oral bioavailability in humans despite a cyclohexane carbonitrile carboxylic acid motif; however, it lacks the basic piperidine present in the query, so this high-F evidence is only partially transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C40"],
      "claim": "Milnacipran has high absolute oral bioavailability (85 ± 3%) in humans, but its structure lacks the carboxylic acid/zwitterion and has low similarity to the query, making it weak contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C44"],
      "claim": "Melperone, containing a piperidine and fluorophenyl, has moderate absolute bioavailability (54 ± 24%), supporting F ≥ 20%, but it lacks the acid group and is structurally distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low because the query is a zwitterionic piperidine carboxylic acid, closely analogous to alvimopan (F = 6%), and the high-F analogues lack the basic amine/acid zwitterion that dominates permeability. The highest-similarity analogue cilomilast is high-F but lacks the basic piperidine, so its transfer is limited.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.32), limiting quantitative transfer.",
    "No permeability or efflux data for the query's specific zwitterionic scaffold.",
    "The effect of the lipophilic cyclohexane carbonitrile/fluorophenyl substituent on overcoming zwitterion-related poor absorption is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

